    assert FILES["drug_targets"]["coverage"] == {
        "drugs": len(drugs), "drugs_with_targets": sum(bool(d["targets"]) for d in drugs),
        "unmapped_items": len(unmapped),
        "unmapped_by_reason": dict(Counter(u["reason"] for u in unmapped)),
